mapper.select:
select userdata_details.username as username, userdata_details.order_item as order_item from "interviewworks_schema"."userdata_details" userdata_details inner join "interviewworks_schema"."userdata" userdata on userdata_details.username = userdata.username inner join "interviewworks_schema"."permissionsdata" permissionsdata on userdata.username = permissionsdata.username
and userdata_details.username = #{username}
and userdata_details.order_item = #{orderItem}
and userdata_details.is_active = '1' and userdata_details.tracking_number is null
order by userdata_details.updated_date desc

mapper.delete:
DELETE
FROM "interviewworks_schema"."quotations" q
WHERE EXISTS (SELECT 1
              FROM "interviewworks_schema"."userdata_details" ud
              WHERE q.username = ud.username
                and ud.username = #{username}
                and q.quotation_id = #{quotation_id}
              )

mapper.update:
update "interviewworks_schema"."quotations"
set status = #{status}
where username = #{username}
  and quotation_id = #{quotation_id}

mapper.select:
select userdata_details.username, quotations.quotation_id, quotations.status from "interviewworks_schema"."userdata_details" userdata_details inner join "interviewworks_schema"."quotations" quotations on userdata_details.username = quotations.username where userdata_details.is_active = '1'
userdata_details.order_item = #{orderItem}
and userdata_details.username = #{username} and quotations.quotation_id = #{quotation_id}

select orders.order_id, orders.quotation_id, orders.status, quotations.username, quotation_items.product_id, quotation_items.quantity from "interviewworks_schema"."orders" orders inner join "interviewworks_schema"."quotations" quotations on orders.quotation_id = orders.quotation_id inner join "interviewworks_schema"."quotation_items" quotation_items on quotations.quotation_id = quotation_items.quotation_id
and orders.order_id = #{order_id}
and quotations.username = #{username}
and quotations.status in
#{quotationsStatus}
and orders.status in
#{status}
order by orders.order_id

select coalesce(max(serial::int), 0) + 1
from "interviewworks_schema"."shipments"
where date_part = #{date_part}
and prefix = #{prefix}

select shipments.order_id, orders.quotation_id, shipments.status, shipments.date_part, shipments.tracking_number, quotations.username, payments.status as payments_status, payments.payments_method as payments_method, payments.amount as payments_amount, orders.total_price as orders_total_price from "interviewworks_schema"."shipments" shipments inner join "interviewworks_schema"."orders" orders on shipments.order_id = orders.order_id inner join "interviewworks_schema"."quotations" quotations on orders.quotation_id = quotations.quotation_id inner join "interviewworks_schema"."payments" payments on orders.order_id = payments.order_id
and shipments.order_id = #{order_id}
and quotations.username = #{username}
and shipments.tracking_number like concat(#{tracking_number}, '%')
and shipments.date_part like concat(#{date_part}, '%')
and quotations.status in
#{quotationsStatus}
and orders.status in
#{ordersStatus}
and shipments.status in
#{shipmentsStatus}
and payments.status in
#{paymentsStatus}
and payments.payments_method in
#{paymentsMethod}
order by shipments.order_id

mapper.update:
update "interviewworks_schema"."userdata_details"
set tracking_number = #{tracking_number},
    is_active_notifications = '0'
where userdata_details.username = #{username}
  and userdata_details.order_item = #{order_item}
